fn smallest_change(arr: Vec<i8>) -> usize {
    let n = arr.len();
    let mut changes = 0;

    // Iterate only through the first half of the array
    for i in 0..n / 2 {
        if arr[i] != arr[n - 1 - i] {
            changes += 1; // Count the difference
        }
    }

    changes
}

fn main() {
    // Example usage
    let arr = vec![1, 2, 3, 2, 1];
    println!("Minimum changes required: {}", smallest_change(arr)); // Output: 0

    let arr2 = vec![1, 2, 3, 4, 5];
    println!("Minimum changes required: {}", smallest_change(arr2)); // Output: 2
}